export function applyBmoNotes(collection) {
  for (const subject of collection.subjects) {
    for (const topic of subject.topics) {
      const translation = bmoNotes[topic.id];
      if (!translation || translation.notes.length !== topic.bullets.length || translation.hints.length !== topic.exercises.length) {
        throw new Error(`Incomplete BMO translation: ${topic.id}`);
      }
      topic.description = translation.description;
      topic.bullets.forEach((item, index) => { item.text = translation.notes[index]; });
      topic.exercises.forEach((item, index) => { item.hint = translation.hints[index]; });
    }
  }
  return collection;
}
